const userId = $input.first().json.userId;
if (!userId) return { json: { error: 'No userId provided' } };
const dbUrl = $input.first().json.databaseUrl || process.env.DATABASE_URL || '';
if (!dbUrl) {
  return { json: { ...$input.first().json, persona: { userId, language_preference: 'th', tokens: {} } } };
}
function getTopStrengths(profile) {
  const scores = { self_awareness: profile.self_awareness, emotional_regulation: profile.emotional_regulation, compassion: profile.compassion, integrity: profile.integrity, growth_mindset: profile.growth_mindset, wisdom: profile.wisdom, transcendence: profile.transcendence };
  return Object.entries(scores).filter(([, v]) => v != null).sort(([, a], [, b]) => b - a).slice(0, 2).map(([k]) => k);
}
try {
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const userResult = await pool.query(`SELECT id, name, email, language_preference, timezone, "subscriptionTier", persona, updated_at FROM "User" WHERE id = $1 LIMIT 1`, [userId]);
  if (userResult.rows.length === 0) { await pool.end(); return { json: { ...$input.first().json, persona: { userId, language_preference: 'th', tokens: {} } } }; }
  const user = userResult.rows[0];
  let personaData = {};
  try { const raw = user.persona; personaData = typeof raw === 'string' ? JSON.parse(raw) : (raw || {}); } catch (e) { personaData = {}; }
  let ethicalProfile = null;
  try {
    const ethResult = await pool.query(`SELECT self_awareness, emotional_regulation, compassion, integrity, growth_mindset, wisdom, transcendence, growth_stage, total_interactions FROM user_data_schema.ethical_profiles WHERE user_id = $1 LIMIT 1`, [userId]);
    if (ethResult.rows.length > 0) {
      const ep = ethResult.rows[0];
      ethicalProfile = { growth_stage: ep.growth_stage || 2, growth_stage_label: ['', 'Beginner', 'Developing', 'Growing', 'Advanced', 'Wise'][ep.growth_stage || 2], top_strengths: getTopStrengths(ep), total_interactions: ep.total_interactions || 0, last_routing: personaData.ethical_summary?.last_routing || null };
    }
  } catch (e) { console.log('[Load Context] ethical_profiles skip:', e.message); }
  let keyFacts = [];
  try {
    const factsResult = await pool.query(`SELECT fact FROM user_data_schema.memory_facts WHERE user_id = $1 ORDER BY created_at DESC LIMIT 10`, [userId]);
    keyFacts = factsResult.rows.map(r => r.fact);
  } catch (e) { console.log('[Load Context] memory_facts skip:', e.message); }
  await pool.end();
  const persona = { userId: user.id, email: user.email, name: user.name || user.email?.split('@')[0], language_preference: user.language_preference || 'th', timezone: user.timezone || 'Asia/Bangkok', subscriptionTier: user.subscriptionTier || 'FREE', interests: personaData.interests || [], preferences: personaData.preferences || {}, physical_stats: personaData.physical_stats || {}, personality_notes: personaData.personality_notes || null, key_facts: keyFacts, ethical_profile: ethicalProfile, relevant_memories: [], _persona_updated: personaData._last_memory_update || null, tokens: {} };
  return { json: { ...$input.first().json, persona } };
} catch (err) {
  console.error('[Load Context] Database error:', err.message);
  return { json: { ...$input.first().json, persona: { userId, language_preference: 'th', tokens: {}, _error: err.message } } };
}

// Load Tokens v5.1 — unchanged from original
const context = $input.first().json;
const userId = context.userId;
if (!userId) return { json: { ...context, persona: { ...context.persona, tokens: {} } } };

const n8nUrl = process.env.N8N_BASE_URL || '';
const n8nEmail = process.env.N8N_USER_EMAIL || '';
const n8nPassword = process.env.N8N_USER_PASSWORD || '';
if (!n8nUrl || !n8nEmail || !n8nPassword) return { json: { ...context, persona: { ...context.persona, tokens: {} } } };

try {
  const loginRes = await fetch(`${n8nUrl}/rest/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ emailOrLdapLoginId: n8nEmail, password: n8nPassword })
  });
  if (!loginRes.ok) return { json: { ...context, persona: { ...context.persona, tokens: {} } } };
  const cookies = loginRes.headers.get('set-cookie') || '';

  const credsRes = await fetch(`${n8nUrl}/rest/credentials`, { headers: { Cookie: cookies } });
  if (!credsRes.ok) return { json: { ...context, persona: { ...context.persona, tokens: {} } } };
  const allCreds = await credsRes.json();
  const userCreds = (allCreds.data || []).filter(c => c.name && c.name.startsWith(`${userId}:`));

  const tokens = {};
  const metadata = {};

  for (const cred of userCreds) {
    try {
      const detailRes = await fetch(`${n8nUrl}/rest/credentials/${cred.id}`, { headers: { Cookie: cookies } });
      if (!detailRes.ok) continue;
      const detail = await detailRes.json();
      const data = detail.data || {};
      const nameParts = cred.name.split(':');
      const service = nameParts[1] || '';

      if (data.oauthTokenData) { const prefix = service === 'google' ? 'google' : service; tokens[`${prefix}_access_token`] = data.oauthTokenData.access_token || ''; tokens[`${prefix}_refresh_token`] = data.oauthTokenData.refresh_token || ''; }
      if (service === 'openrouter' && data.apiKey) tokens.openrouter_access_token = data.apiKey;
      if (service === 'line_notify' && data.value) tokens.line_notify_token = data.value.replace('Bearer ', '');
      if (service === 'youtube_api' && data.apiKey) tokens.youtube_api_key = data.apiKey;
      if (service === 'google_maps' && data.apiKey) tokens.google_maps_key = data.apiKey;
      if (service === 'openweathermap' && data.accessToken) tokens.openweathermap_key = data.accessToken;
      if (service === 'brave_search' && data.value) tokens.brave_api_key = data.value;
      if (service === 'finnhub' && data.apiKey) tokens.finnhub_api_key = data.apiKey;
      if (service === 'nutritionix') { tokens.nutritionix_app_id = data.value || ''; tokens.nutritionix_api_key = data.additionalHeaders?.['x-app-key'] || ''; }
      if (service === 'fal_ai' && data.value) tokens.fal_api_key = data.value.replace('Key ', '');
      if (service === 'unsplash' && data.value) tokens.unsplash_access_key = data.value.replace('Client-ID ', '');
      if (service === 'telegram' && data.accessToken) tokens.telegram_bot_token = data.accessToken;
      if (service === 'discord_bot' && data.accessToken) tokens.discord_bot_token = data.accessToken;
      if (service === 'elevenlabs' && data.apiKey) tokens.elevenlabs_api_key = data.apiKey;
      if (service === 'elevenlabs_voice_id' && data.value) metadata.elevenlabs_voice_id = data.value;
      if (service === 'lastfm' && data.value) tokens.lastfm_api_key = data.value;
      if (service === 'lastfm_username' && data.value) metadata.lastfm_username = data.value;
      if (service === 'lastfm_session' && data.value) metadata.lastfm_session_key = data.value;
      if (service === 'home_assistant' && data.value) tokens.ha_token = data.value.replace('Bearer ', '');
      if (service === 'home_assistant_url' && data.user) metadata.ha_url = data.user;
      if (service === 'sonos' && data.user) metadata.sonos_api_url = data.user;
    } catch (err) { console.log(`[Load Tokens] Error ${cred.name}:`, err.message); }
  }

  return { json: { ...context, persona: { ...context.persona, tokens: { ...tokens, ...metadata } } } };
} catch (err) {
  console.error('[Load Tokens] Error:', err.message);
  return { json: { ...context, persona: { ...context.persona, tokens: {} } } };
}

// ═══════════════════════════════════════════════════════════════
// Memory Injector v1 — Auto inject relevant memories into persona
// ═══════════════════════════════════════════════════════════════
// ทำงาน: embed message ปัจจุบัน → vector search → inject ใน persona
// ผลลัพธ์: ทุก WF3x agent ได้รับ relevant_memories โดยอัตโนมัติ
// ไม่ต้องรอให้ LLM ตัดสินใจเรียก search_memories tool
// ═══════════════════════════════════════════════════════════════

const context = $input.first().json;
const message = context.message || '';
const persona = context.persona || {};
const userId = context.userId;
const dbUrl = context.databaseUrl || process.env.DATABASE_URL || '';

// ── ดึง OpenRouter key (user key ก่อน, ถ้าไม่มีใช้ system key) ──
const embedKey = persona.tokens?.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

// ── ถ้าไม่มี key หรือ message สั้นเกิน → pass through ─────────
if (!embedKey || !dbUrl || !message || message.length < 5 || !userId) {
  console.log('[MemoryInjector] Skip: missing key/db/message');
  return { json: context };
}

let injectedMemories = [];
let injectedFacts = persona.key_facts || [];

try {
  // ── Step 1: Embed current message ──────────────────────────
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${embedKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'openai/text-embedding-3-small',
      input: message
    })
  });

  if (!embedRes.ok) {
    console.warn(`[MemoryInjector] Embed failed: ${embedRes.status}`);
    return { json: context };
  }

  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding) {
    console.warn('[MemoryInjector] No embedding returned');
    return { json: context };
  }

  // ── Step 2: Vector search relevant memories ─────────────────
  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;

  // Search memory_embeddings (vector similarity > 0.55)
  const memResult = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2
       AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.55
     ORDER BY embedding <=> $1::vector
     LIMIT 5`,
    [vectorStr, userId]
  );

  // Also search interaction_memories for context (non-vector, recent + matching type)
  const interactionResult = await pool.query(
    `SELECT text, classification, reflection_prompt, gentle_guidance, created_at
     FROM user_data_schema.interaction_memories
     WHERE user_id = $1
       AND classification IN ('growth_memory', 'wisdom_moment', 'challenge_memory')
     ORDER BY created_at DESC
     LIMIT 3`,
    [userId]
  );

  await pool.end();

  // ── Step 3: Build injected memories ────────────────────────
  injectedMemories = [
    ...memResult.rows.map(r => ({
      summary: (r.content || '').slice(0, 150) + (r.content?.length > 150 ? '...' : ''),
      type: r.metadata?.classification || 'memory',
      similarity: parseFloat((r.similarity || 0).toFixed(3)),
      date: new Date(r.created_at).toLocaleDateString('th-TH'),
      source: 'vector_search'
    })),
    ...interactionResult.rows.map(r => ({
      summary: (r.text || '').slice(0, 150) + (r.text?.length > 150 ? '...' : ''),
      type: r.classification,
      insight: r.reflection_prompt || null,
      date: new Date(r.created_at).toLocaleDateString('th-TH'),
      source: 'interaction_memory'
    }))
  ];

  // Deduplicate by summary prefix (avoid showing same content twice)
  const seen = new Set();
  injectedMemories = injectedMemories.filter(m => {
    const key = m.summary.slice(0, 50);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 5); // max 5 memories injected

  console.log(`[MemoryInjector] ✅ userId=${userId.slice(0,8)}... | memories=${injectedMemories.length} | facts=${injectedFacts.length}`);

} catch (err) {
  // Non-fatal: memory injection failure should not block response
  console.warn('[MemoryInjector] Error (non-fatal):', err.message);
}

// ── Inject into persona ────────────────────────────────────────
return {
  json: {
    ...context,
    persona: {
      ...persona,
      relevant_memories: injectedMemories,  // ← WF3x reads this
      key_facts: injectedFacts,              // ← already loaded from DB
      _memory_injected: injectedMemories.length > 0,
      _memory_injected_at: new Date().toISOString()
    }
  }
};

// JARVIS Intent Router v5.2 — unchanged logic, just updated position
const payload  = $input.first().json;
const message  = payload.message || '';
const persona  = payload.persona || {};
const lang     = persona.language_preference || 'th';
const name     = persona.name || 'User';
const tier     = persona.subscriptionTier || 'FREE';
const stage    = persona.ethical_profile?.growth_stage || 2;
const stageLabel = persona.ethical_profile?.growth_stage_label || 'Developing';
const interests  = (persona.interests || []).slice(0, 5).join(', ') || 'not specified';
const keyFacts   = (persona.key_facts || []).slice(0, 3).join(' | ') || 'none';
const recentMemTypes = (persona.relevant_memories || []).map(m => m.type).join(', ') || 'none';

const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';
const userKey   = persona.tokens?.openrouter_access_token || '';
const systemKey = process.env.OPENROUTER_API_KEY || '';

const n8nBase = process.env.N8N_BASE_URL || 'http://localhost:5678';
const AGENT_URLS = {
  wf3a: process.env.N8N_WF3A_URL || `${n8nBase}/webhook/wf3a-secretary`,
  wf3b: process.env.N8N_WF3B_URL || `${n8nBase}/webhook/wf3b-soul`,
  wf3c: process.env.N8N_WF3C_URL || `${n8nBase}/webhook/wf3c-careercoach`,
  wf3d: process.env.N8N_WF3D_URL || `${n8nBase}/webhook/wf3d-explorer`,
  wf3e: process.env.N8N_WF3E_URL || `${n8nBase}/webhook/wf3e-creator`,
  wf3f: process.env.N8N_WF3F_URL || `${n8nBase}/webhook/wf3f-homemate`,
  wf3g: process.env.N8N_WF3G_URL || `${n8nBase}/webhook/wf3g-healthcoach`
};

const SYSTEM_PROMPT = `You are JARVIS — the central cognitive router of an advanced personal AI system.
Your function: Decompose the user's message into a structured dispatch plan.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
AGENT REGISTRY
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

wf3a [SECRETARY] — External coordination & communication
  • Calendar, reminders, alarms, countdowns, scheduling
  • Email, LINE notify, Telegram, Discord, Slack, SMS
  • Social media: post, DM, tweet, LinkedIn
  • Task management: todo, checklist, Notion, Trello

wf3b [SOUL] — Inner world, emotions & personal growth
  • Emotional processing: venting, sharing feelings, being heard
  • Journaling: daily log, gratitude, mood entry, reflection
  • Personal growth: habits, streaks, mindfulness, meditation
  • Relationships: emotional angle
  • Crisis: hopelessness, self-harm → ALWAYS wf3b, ALWAYS crisis=true

