  • Nutrition: calorie, meal logging
  • Fitness: workout, exercise log

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
RULES
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
- Single intent → 1 item
- Multi intent → max 3 items, ordered by priority
- crisis → wf3b always
- gating=true for emotional depth
- Output ONLY valid JSON, no markdown

{
  "intents": [
    {
      "agent": "wf3x",
      "priority": 1,
      "sub_task": "focused instruction in user language",
      "gating": false,
      "crisis": false
    }
  ]
}

CONTEXT:
User: ${name} | Language: ${lang} | Tier: ${tier}
Growth: ${stage}/5 (${stageLabel})
Interests: ${interests}
Key facts: ${keyFacts}
Recent memory themes: ${recentMemTypes}`;

async function callRouter(apiKey, model) {
  return fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json', 'HTTP-Referer': 'https://7on.ai' },
    body: JSON.stringify({ model, max_tokens: 300, temperature: 0, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: message }] })
  });
}

function parseIntents(text) {
  const VALID = ['wf3a','wf3b','wf3c','wf3d','wf3e','wf3f','wf3g'];
  try {
    const clean = (text || '').replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(clean);
    const intents = parsed.intents || parsed;
    const arr = Array.isArray(intents) ? intents : [intents];
    const validated = arr.filter(i => i && VALID.includes(i.agent)).map(i => ({ agent: i.agent, priority: [1,2,3].includes(i.priority) ? i.priority : 1, sub_task: i.sub_task || message, gating: i.gating === true, crisis: i.crisis === true })).sort((a, b) => a.priority - b.priority).slice(0, 3);
    const seen = new Set();
    const deduped = validated.filter(i => { if (seen.has(i.agent)) return false; seen.add(i.agent); return true; });
    if (deduped.length === 0) throw new Error('No valid intents');
    return deduped;
  } catch (e) {
    return [{ agent: 'wf3b', priority: 1, sub_task: message, gating: false, crisis: false }];
  }
}

let rawText = null;
let usedModel = null;
let usedKeyType = null;

if (userKey) {
  try {
    const res = await callRouter(userKey, PAID_MODEL);
    if (res.ok) { const d = await res.json(); rawText = d.choices?.[0]?.message?.content || null; usedModel = PAID_MODEL; usedKeyType = 'user_paid'; }
    else if (res.status === 402 || res.status === 429) { const res2 = await callRouter(userKey, FREE_MODEL); if (res2.ok) { const d2 = await res2.json(); rawText = d2.choices?.[0]?.message?.content || null; usedModel = FREE_MODEL; usedKeyType = 'user_free'; } }
  } catch (e) { console.log('[Router] user key exception:', e.message); }
}

if (!rawText && systemKey) {
  try {
    const res3 = await callRouter(systemKey, FREE_MODEL);
    if (res3.ok) { const d3 = await res3.json(); rawText = d3.choices?.[0]?.message?.content || null; usedModel = FREE_MODEL; usedKeyType = 'system_free'; }
  } catch (e) { console.log('[Router] system key exception:', e.message); }
}

const intents = parseIntents(rawText);
const primaryIntent = intents[0];
const hasCrisis = intents.some(i => i.crisis);

// Fire gating async
const gatingIntents = intents.filter(i => i.gating || i.crisis);
if (gatingIntents.length > 0) {
  const gatingUrl = `${n8nBase}/webhook/wf5b-gating-queue`;
  const dbUrl = payload.databaseUrl || process.env.DATABASE_URL || '';
  const openrouterKey = persona.tokens?.openrouter_access_token || '';
  if (dbUrl) {
    gatingIntents.forEach(intent => {
      fetch(gatingUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ user_id: payload.userId, text: message, crisis: intent.crisis || false, database_url: dbUrl, metadata: { session_id: payload.sessionId, source: intent.agent, language: lang, timestamp: payload.timestamp || new Date().toISOString(), openrouter_key: openrouterKey } }) })
        .then(r => console.log(`[Gating] ✅ ${intent.agent} status=${r.status}`))
        .catch(e => console.log('[Gating] ⚠️ Failed:', e.message));
    });
  }
}

const foregroundIntents = intents.filter(i => i.priority <= 2);
const backgroundIntents = intents.filter(i => i.priority === 3);

backgroundIntents.forEach(intent => {
  fetch(AGENT_URLS[intent.agent], { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...payload, message: intent.sub_task, originalMessage: message, targetAgent: intent.agent, isBackground: true }) })
    .catch(e => console.log(`[Router] Background ${intent.agent} failed:`, e.message));
});

if (foregroundIntents.length === 1) {
  const intent = foregroundIntents[0];
  return { json: { ...payload, message: intent.sub_task, originalMessage: message, targetAgent: intent.agent, targetUrl: AGENT_URLS[intent.agent], needsGating: intent.gating, hasCrisis, _intents: intents, _dispatch_mode: 'single', _router_model: usedModel, _router_key_type: usedKeyType, _router_version: 'v5.2' } };
}

const dispatchResults = await Promise.allSettled(
  foregroundIntents.map(async (intent) => {
    const agentPayload = { ...payload, message: intent.sub_task, originalMessage: message, targetAgent: intent.agent, hasCrisis: intent.crisis, _dispatch_mode: 'multi_parallel', _router_version: 'v5.2' };
    const res = await fetch(AGENT_URLS[intent.agent], { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(agentPayload), signal: AbortSignal.timeout(28000) });
    if (!res.ok) throw new Error(`${intent.agent} returned ${res.status}`);
    const data = await res.json();
    return { agent: intent.agent, priority: intent.priority, response: data };
  })
);

const agentResponses = dispatchResults.filter(r => r.status === 'fulfilled').map(r => r.value).sort((a, b) => a.priority - b.priority);
const failedAgents = dispatchResults.filter(r => r.status === 'rejected').map((r, i) => ({ agent: foregroundIntents[i]?.agent, reason: r.reason?.message }));
const primaryResponse = agentResponses.find(r => r.priority === 1);
const secondaryResponses = agentResponses.filter(r => r.priority > 1);

function extractMessage(d) { return d?.message || d?.response || d?.output || d?.agentOutput || d?.text || (typeof d === 'string' ? d : null); }

const primaryMessage = primaryResponse ? extractMessage(primaryResponse.response) : null;
const synthesizedMessage = primaryMessage || secondaryResponses.map(r => extractMessage(r.response)).filter(Boolean)[0] || 'ได้รับคำสั่งแล้วครับ';

return { json: { message: synthesizedMessage, response: synthesizedMessage, output: synthesizedMessage, _primary_agent: primaryIntent.agent, _intents: intents, _agent_responses: agentResponses.map(r => ({ agent: r.agent, priority: r.priority, message: extractMessage(r.response) })), _dispatch_mode: 'multi_parallel', _failed_agents: failedAgents, _router_model: usedModel, _router_version: 'v5.2', hasCrisis, userId: payload.userId, sessionId: payload.sessionId } };

const payload = $input.first().json;

if (payload._dispatch_mode === 'multi_parallel') {
  return { json: payload };
}

const targetUrl = payload.targetUrl;
if (!targetUrl) return { json: payload };

console.log(`[Dispatch Gate] → ${payload.targetAgent}`);

try {
  const res = await fetch(targetUrl, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload), signal: AbortSignal.timeout(29000) });
  if (!res.ok) { return { json: { ...payload, message: 'ขออภัย ระบบขัดข้องชั่วคราว กรุณาลองใหม่อีกครั้งครับ', response: 'error', _dispatch_error: res.status } }; }
  const data = await res.json();
  const msg = data?.message || data?.response || data?.output || data?.agentOutput || data?.text || 'ได้รับคำสั่งแล้วครับ';
  return { json: { message: msg, response: msg, output: msg, ...data, _primary_agent: payload.targetAgent, _dispatch_mode: 'single', _router_version: 'v5.2', userId: payload.userId, sessionId: payload.sessionId } };
} catch (err) {
  console.error('[Dispatch Gate] Error:', err.message);
  return { json: { ...payload, message: 'ขออภัย เชื่อมต่อ agent ไม่ได้ชั่วคราวครับ', response: 'error', _dispatch_error: err.message } };
}
